SELECT s1.`c0` AS `id`, s1.`c1` AS `customer`, s1.`c2` AS `amount` FROM (SELECT s5.`c0` AS `c0`, s5.`c1` AS `c1`, s5.`c2` AS `c2`, ROW_NUMBER() OVER (ORDER BY s5.`c2` ASC NULLS LAST) AS `o` FROM (SELECT s2.`c0` AS `c0`, s2.`c1` AS `c1`, s2.`c2` AS `c2` FROM (SELECT s3.`c3` AS `c0`, s3.`c4` AS `c1`, s3.`c5` AS `c2` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c0` AS `c3`, s4.`c1` AS `c4`, s4.`c2` AS `c5` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2` FROM `orders`) AS s4) AS s3) AS s2 ORDER BY s2.`c2` ASC NULLS LAST LIMIT 2 OFFSET 1) AS s5) AS s1 ORDER BY s1.`o` ASC NULLS LAST
